using CarShow.Domain.Enums;

namespace CarShow.Domain.Entities; // Replace namespace with your project's namespace

public class Registration
{
    public Guid Id { get; set; } = Guid.NewGuid();

    // 1. Generated by the server, unique, format CS27-0001, CS27-0002, ...
    public string RegistrationNumber { get; set; } = string.Empty;

    // 2. Set by the server (UTC) when the registration is created
    public DateTime RegistrationDate { get; set; }

    // 3. Required, max 150
    public string ParticipantName { get; set; } = string.Empty;

    // 4. Required, PH mobile format 09XXXXXXXXX (11 digits)
    public string ContactNumber { get; set; } = string.Empty;

    // 5. Required, valid email, max 200
    public string Email { get; set; } = string.Empty;

    // 6. Required, max 300
    public string Address { get; set; } = string.Empty;

    // 7. Required, max 100 (e.g. Toyota Supra MK4)
    public string CarMakeModel { get; set; } = string.Empty;

    // 8. Required, max 15, unique (one car = one registration)
    public string PlateNumber { get; set; } = string.Empty;

    // 9. enum: Exhibitor, Competitor, VIP
    public RegistrationType RegistrationType { get; set; }

    // 10. enum: Pending, Confirmed, CheckedIn, Cancelled (default Pending)
    public RegistrationStatus Status { get; set; } = RegistrationStatus.Pending;

    // 11. Set by the server from the type (Exhibitor=1500, Competitor=2500, VIP=5000)
    public decimal RegistrationFee { get; set; }

    // 12. 0 up to RegistrationFee
    public decimal AmountPaid { get; set; }

    // --- Business Rule Helpers ---

    public static decimal CalculateFee(RegistrationType type) => type switch
    {
        RegistrationType.Exhibitor => 1500.00m,
        RegistrationType.Competitor => 2500.00m,
        RegistrationType.VIP => 5000.00m,
        _ => throw new ArgumentOutOfRangeException(nameof(type), "Invalid registration type.")
    };

    public string GetPaymentStatus()
    {
        if (AmountPaid <= 0) return "Unpaid";
        if (AmountPaid < RegistrationFee) return "Partial";
        return "Paid";
    }
}